(() => {
  // Navya-only 3D presentation: a transparent, high-detail cut-out matching the supplied reference.
  // A single reference image cannot provide a fully sculpted, rigged 3D mesh; this keeps her likeness exact
  // and adds a transparent WebGL scene, perspective, gentle rotation, and interactive drag rotation.
  const toggle = document.getElementById('navya3DToggle');
  const canvas = document.getElementById('navya3DCanvas');
  const wrap = document.querySelector('.character-wrap');
  if (!toggle || !canvas || !wrap) return;
  let renderer, scene, camera, model, frame, active = false, dragging = false, lastX = 0, resizeObserver, targetTiltX = 0, targetTiltY = 0;
  const setFallback = () => {
    toggle.disabled = true;
    toggle.textContent = '✨ 3D view needs an internet connection';
    toggle.title = 'Three.js could not load. Navya’s original portrait remains available.';
  };
  function init() {
    if (!window.THREE) { setFallback(); return; }
    renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setClearColor(0x000000, 0);
    if ('outputColorSpace' in renderer) renderer.outputColorSpace = THREE.SRGBColorSpace;
    scene = new THREE.Scene();
    camera = new THREE.PerspectiveCamera(32, 1, .1, 100);
    camera.position.set(0, 0, 7.2);
    scene.add(new THREE.HemisphereLight(0xffeaff, 0x35306b, 1.8));
    const key = new THREE.DirectionalLight(0xffe0b9, 1.5); key.position.set(3, 5, 5); scene.add(key);
    const rim = new THREE.PointLight(0x9c7bff, 1.8, 10); rim.position.set(-3, 2, 2); scene.add(rim);
    model = new THREE.Group(); scene.add(model);
    const loader = new THREE.TextureLoader();
    loader.load('data:image/png;base64,', texture => {
      if ('colorSpace' in texture) texture.colorSpace = THREE.SRGBColorSpace;
      texture.minFilter = THREE.LinearMipmapLinearFilter;
      texture.magFilter = THREE.LinearFilter;
      const material = new THREE.MeshBasicMaterial({ map: texture, transparent: true, alphaTest: .025, side: THREE.DoubleSide, depthWrite: false });
      // The transparent texture preserves the exact crown, curls, blue gown, shoes and star wand.
      const portrait = new THREE.Mesh(new THREE.PlaneGeometry(3.75, 5.625), material);
      portrait.position.y = -.02;
      model.add(portrait);
    }, undefined, () => { toggle.textContent = '✨ Navya image failed to decode'; toggle.title = 'Try a modern browser with WebGL enabled.'; });
    // Small floating sparkles add depth without placing a background behind Navya.
    const sparkleGroup = new THREE.Group(); scene.add(sparkleGroup);
    for (let i = 0; i < 24; i++) {
      const geo = new THREE.OctahedronGeometry(.025 + (i % 3) * .012, 0);
      const mat = new THREE.MeshBasicMaterial({ color: i % 2 ? 0xe9d7ff : 0xffe7a4, transparent: true, opacity: .75 });
      const star = new THREE.Mesh(geo, mat);
      star.position.set(Math.sin(i * 2.1) * 1.65, Math.cos(i * 1.6) * 2.35, .18 + Math.sin(i) * .25);
      sparkleGroup.add(star);
    }
    resizeObserver = new ResizeObserver(resize); resizeObserver.observe(wrap);
    function animate() {
      frame = requestAnimationFrame(animate);
      if (model && !dragging) {
        model.rotation.y += .0012;
        model.rotation.x += (targetTiltX - model.rotation.x) * .045;
        // Small pointer-driven turn makes the cut-out feel responsive without pretending it has a rigged head.
        model.rotation.y += (targetTiltY - model.rotation.y) * .025;
      }
      if (model) model.position.y = Math.sin(Date.now() * .0012) * .035;
      sparkleGroup.rotation.y += .001;
      renderer.render(scene, camera);
    }
    animate(); resize();
    canvas.addEventListener('pointerdown', e => { dragging = true; lastX = e.clientX; canvas.setPointerCapture(e.pointerId); });
    canvas.addEventListener('pointermove', e => { if (dragging && model) { model.rotation.y += (e.clientX - lastX) * .009; lastX = e.clientX; } });
    ['pointerup', 'pointercancel', 'lostpointercapture'].forEach(ev => canvas.addEventListener(ev, () => dragging = false));
  }
  function resize() {
    if (!renderer || !camera) return;
    const w = Math.max(1, wrap.clientWidth), h = Math.max(1, wrap.clientHeight);
    renderer.setSize(w, h, false); camera.aspect = w / h; camera.updateProjectionMatrix();
  }
  // Desktop cursor and mobile touch adapt the whole portrait's subtle tilt.
  wrap.addEventListener('pointermove', e => {
    if (!active || dragging) return;
    const rect = wrap.getBoundingClientRect();
    const nx = ((e.clientX - rect.left) / Math.max(1, rect.width)) * 2 - 1;
    const ny = ((e.clientY - rect.top) / Math.max(1, rect.height)) * 2 - 1;
    targetTiltY = Math.max(-.13, Math.min(.13, nx * .13));
    targetTiltX = Math.max(-.07, Math.min(.07, -ny * .07));
  }, { passive: true });
  wrap.addEventListener('pointerleave', () => { targetTiltX = 0; targetTiltY = 0; });

  toggle.addEventListener('click', () => {
    if (!window.THREE) { setFallback(); return; }
    if (!renderer) init();
    if (!renderer) return;
    active = !active; canvas.hidden = !active; wrap.classList.toggle('model-mode', active);
    toggle.setAttribute('aria-pressed', String(active));
    toggle.textContent = active ? '🖼️ Show Navya’s portrait' : '✨ Meet Navya in 3D';
    if (active) resize();
  });
  if (!window.THREE) setTimeout(() => { if (!window.THREE) setFallback(); }, 1200);
})();
